mapper.select:
select u.user_id, u.nick_name, u.user_name, u.avatar, u.phonenumber, u.sex, u.member_no, u.member_department, u.member_title, u.member_cohort, u.student_no, u.class_name, u.is_quanta_member, u.major, r.cohort_id, r.role_category, r.member_status, r.join_time, r.retain_flag, case when r.role_category in ('MANAGER','INTERN') and ifnull(r.retain_flag,'0') = '0' and c.is_current = '1' and r.member_status = 'ACTIVE' then '1' else '0' end as can_retain from sys_user u left join qt_member_record r on u.user_id = r.user_id left join qt_cohort c on r.cohort_id = c.cohort_id where u.del_flag = '0' and u.is_quanta_member = '1'
and r.cohort_id = #{cohortId}
and r.member_status = #{memberStatus}
and r.role_category = #{roleCategory}
and ( u.nick_name like concat('%', #{nickName}, '%') or u.user_name like concat('%', #{nickName}, '%') or u.member_department like concat('%', #{nickName}, '%') or u.member_no like concat('%', #{nickName}, '%') )
and u.member_department like concat('%', #{memberDepartment}, '%')
and u.member_cohort = #{memberCohort}
order by u.member_cohort desc, u.member_no asc, u.user_id asc
